  "loc.enterInternetConnectionsAddress": "Informe como servidor o endereço da sua conexão de internet (por exemplo, seu endereço MyFRITZ!) – geralmente por comando SMS, conforme o manual do rastreador.",
  "loc.enterShopAddressesUnder": "Você informa os endereços das lojas em Listas → Editar lista de compras – se uma loja existir mais de uma vez, também várias filiais. Se alguém ficar lá um tempo, a ida às compras planejada é marcada.",
