  "loc.gettingLocation": "A obter localização …",
  "loc.gpsTracker": "🛰️ Rastreador GPS",
  "loc.guide1": "Instale a app <b>«Traccar Client»</b> (App Store ou Google Play, gratuita).",
  "loc.guide2": "Na app, introduza em <b>ID do dispositivo</b> (Device identifier):",
  "loc.guide3": "Introduza em <b>URL do servidor</b>:",
  "loc.guide4": "Precisão <b>Média</b>, distância <b>50 m</b>. A app só envia quando te moves – parado, nada. Se houver mais campos (intervalo, heartbeat), heartbeat desligado ou 0.",
  "loc.guide5": "Permita o acesso à localização: <b>Sempre</b> e <b>Localização exata</b> ativada.",
  "loc.guide6": "Ative o interruptor <b>Serviço / Rastreamento</b> e <b>deixe-o sempre ligado</b> – pronto. A partir de agora controlas tudo no pinn.: «Enviar continuamente» ligado ou desligado, «Enviar uma vez» e SOS. Enquanto «Enviar continuamente» estiver desligado, ninguém vê a tua localização e o pinn. não regista nenhum percurso.",
  "loc.guideIntro": "Sem outra app, «📍 Partilhar localização» funciona diretamente no pinn. – mas só enquanto o pinn. está aberto. Para que a localização chegue também com o pinn. fechado e o ecrã bloqueado, a app gratuita «Traccar Client» envia-a diretamente para o pinn. (não é preciso servidor Traccar). Igual em iPhone e Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Esta porta precisa ser liberada para o NAS na FRITZ!Box, porque o rastreador se conecta pela rede móvel.",
  "loc.haveGoodTripFamily": "Boa viagem! A família foi informada.",
