  "settings.calendar.fromFamily#wg": "da casa compartilhada · pinn.",
  "settings.calendar.info": "Cada perfil entra com a própria conta do iCloud ou do Google e marca os calendários dela: “Para mim” só o próprio perfil vê; “Família” todos da sua família veem e usam. Os outros só veem de qual conta vem um calendário da família – com o endereço ocultado, por exemplo, m**l@g***l.com. Compromissos podem ser criados, editados, movidos e deixados na fila off-line como de costume e vão direto para o iCloud ou o Google (e, assim, para o celular). Sincronização a cada 15 minutos ou com “Atualizar agora”. Sem conta, também funciona um calendário só no seu servidor pinn. Lembretes e resumo diário por push: compromissos privados só para você.",
  "settings.calendar.info#wg": "Cada perfil entra com a própria conta do iCloud ou do Google e marca os calendários dela: “Para mim” só o próprio perfil vê; “Casa compartilhada” todos da sua casa compartilhada veem e usam. Os outros só veem de qual conta vem um calendário da casa compartilhada – com o endereço ocultado, por exemplo, m**l@g***l.com. Compromissos podem ser criados, editados, movidos e deixados na fila off-line como de costume e vão direto para o iCloud ou o Google (e, assim, para o celular). Sincronização a cada 15 minutos ou com “Atualizar agora”. Sem conta, também funciona um calendário só no seu servidor pinn. Lembretes e resumo diário por push: compromissos privados só para você.",
