  "smart.guide1": "1. Novo atalho “pinn Automatik”:",
  "smart.guide10": "Para isso, o aparelho precisa alcançar o pinn. (Wi-Fi de casa ou VPN). Cada ação roda só uma vez por tarefa; o que já foi iniciado pelo botão não é iniciado de novo pela automação.",
  "smart.guide2": "• “Obter conteúdo da URL” – cole o link acima",
  "smart.guide3": "• “Obter valor do dicionário” – chave “aktionen”",
  "smart.guide4": "• “Repetir com cada item”, dentro dele:",
  "smart.guide5": "– “Obter valor do dicionário” – chave “eingabe” de “Repetir item”",
  "smart.guide6": "– “Obter valor do dicionário” – chave “kurzbefehl” de “Repetir item”",
  "smart.guide7": "– “Executar atalho” – escolha o valor “kurzbefehl” como atalho e o valor “eingabe” como entrada",
  "smart.guide8": "2. Aba “Automação” → “Hora do dia” – uma automação por horário no topo, “Executar imediatamente” → “pinn Automatik”.",
  "smart.guide9": "3. Dica: além disso, “Chegar” (Casa) → “pinn Automatik” – recupera o que foi perdido.",
  "smart.haAddress": "Endereço",
