  "smart.haDevices": "Dispositivos pelo Home Assistant: {list}",
  "smart.haIntro": "O servidor do pinn. controla o Home Assistant diretamente – os botões funcionam em qualquer aparelho (inclusive Android), a automação e “Ao marcar” rodam sem atalhos. Com uma entidade de status, o pinn. espera até que, por exemplo, o robô aspirador realmente termine.",
