  "smart.haNoDevices": "Ainda não há dispositivos pelo Home Assistant – crie um dispositivo na aba “Dispositivos” e escolha “Home Assistant”.",
  "smart.haNotConnected": "O Home Assistant ainda não está conectado.",
  "smart.haOff": "Home Assistant não conectado",
  "smart.haOn": "Home Assistant conectado",
  "smart.haSearching": "Procurando o Home Assistant …",
  "smart.haTip1": "Roborock: crie o dispositivo “Robô aspirador”, escolha acima o robô (vacuum.…) – o pinn. carrega os cômodos do mapa. Por ação “Limpeza de cômodo”, com cômodos e modo (aspirar, aspirar e passar pano, passar pano). “Cômodo da tarefa” usa o cômodo da limpeza da casa – os nomes precisam ser iguais aos do app Roborock.",
  "smart.haTip2": "O robô também serve de status: a próxima ação só começa quando ele voltar à base.",
  "smart.haTip3": "Os scripts recebem o nome do cômodo na variável <span class=\"font-mono\">raum</span> – assim um único script atende todos os cômodos.",
  "smart.haTip4": "Luzes/LEDs: defina cor e brilho direto na ação.",
  "smart.haTip5": "A automação roda no servidor a cada minuto – não é preciso automação no celular.",
  "smart.haToken": "Token de acesso de longa duração",
  "smart.haTokenHint": "No Home Assistant: embaixo à esquerda no seu perfil → aba “Segurança” → “Tokens de acesso de longa duração” → “Criar token” e cole a sequência longa inteira. Não precisa escrever “Bearer” antes – o pinn. acrescenta sozinho (e também não atrapalha). O token fica no servidor e nunca é enviado aos aparelhos.",
